CY.i18n.cards("de", {
  arrive: "{n} trat durch die Haustür und bat darum, ein paar Tage bleiben zu dürfen.",
  ok: "Vor dem Abschied ließ {n} etwas zurück: {s}. Dazu sagte {n}: „{q}“",
  miss: "{n} bedankte sich und ging zurück durch die Tür."
}, {
  nightingale: ["Florence Nightingale", "19. Jahrhundert, Großbritannien", "Eine Öllampe", "", "Sie rieb sich die Augen: „Ich habe schon lange keine ganze Nacht mehr durchgeschlafen.“", "Sie sah deine Familie an: „Wer sich um andere kümmert, braucht auch jemanden, der sich um ihn kümmert.“", "Sie schlief stundenlang und wachte deutlich erholter auf.",
    { arrive: "Florence Nightingale trat durch die Haustür und bat, ein Bett auszuleihen, weil sie zu viele Menschen gepflegt hatte.", ok: "Vor dem Abschied sagte Florence Nightingale, du sorgst gut für deine Familie, und bat dich, so weiterzumachen. Sie ließ eine Öllampe zurück.", miss: "Florence Nightingale bedankte sich leise und ging zurück durch die Tür." }],
  zhuge: ["Zhuge Liang", "Drei Reiche, Shu Han", "Ein Federfächer", "", "Er winkte ab: „So viele Dinge, große und kleine, und nachts schlafe ich nie ruhig.“", "Er lächelte: „Jemand sagte einmal, ich äße wenig und erledigte zu viel. Das war nicht falsch.“", "Er schlief bis zur Dämmerung und wachte ganz erfrischt auf.",
    { arrive: "Zhuge Liang trat durch die Haustür, mit dunklen Ringen unter den Augen, und fragte, ob er ein Bett ausleihen dürfe.", ok: "Vor dem Abschied sagte Zhuge Liang, die Familie sei das Wichtigste, und bat dich, dich nicht zu überarbeiten. Er ließ einen Federfächer zurück.", miss: "Zhuge Liang verbeugte sich dankend und ging zurück durch die Tür." }],
  curie: ["Marie Curie", "19. und 20. Jahrhundert, Polen und Frankreich", "Eine Kopie einer Notizbuchseite", "", "Sie versteckte die Hände hinter dem Rücken: „Meine Finger schmerzen manchmal, wahrscheinlich vom Labor.“", "Sie betrachtete neugierig deine Lampe: „Gibt es etwas, das diese unsichtbaren Strahlen aufhalten kann?“", "Sie zog es an und nickte ernst.",
    { arrive: "Marie Curie trat durch die Haustür und sagte, sie sei ewig nicht aus dem Labor herausgekommen und würde gern ein paar Tage bleiben.", ok: "Vor dem Abschied ließ Marie Curie dir die Kopie einer Notizbuchseite da: „Danke, dass du daran gedacht hast.“", miss: "Marie Curie, in Gedanken bei ihren Experimenten, verabschiedete sich eilig und ging zurück.", late: "Beim Hinausgehen sagte sie leise: „Deine Absicht habe ich verstanden, aber ich brauchte eher etwas, das meine Hände schützt.“" }],
  galois: ["Évariste Galois", "19. Jahrhundert, Frankreich", "Ein Blatt voller Formeln", "Danke, dass du bemerkt hast, wie knapp meine Zeit war.", "Er schrieb unablässig, und am Rand stand eine Zeile: „Ich habe keine Zeit.“", "Er sagte, er müsse heute Nacht alles aufschreiben, falls es morgen zu spät sei.", "Er nahm es entgegen und beugte sich sofort schreibend über den Tisch."],
  mozart: ["Wolfgang Amadeus Mozart", "18. Jahrhundert, Österreich", "Eine Kopie einer Notenseite", "Musik ist für die, die zuhören. Danke fürs Zuhören.", "Er summte eine Melodie und sagte, sie werde in eine neue Oper kommen.", "Er fragte, ob es im Haus etwas gebe, in das man blasen könne, und sei es nur eines.", "Er spielte zwei Töne, und seine Augen leuchteten auf."],
  beethoven: ["Ludwig van Beethoven", "18. und 19. Jahrhundert, Deutschland", "Eine Kopie einer Seite aus einem Konversationsheft", "Wenn sich jemand die Mühe macht, mir etwas aufzuschreiben, bin ich nicht allein.", "Er zeigte auf seine Ohren, winkte ab und deutete an, du solltest aufschreiben, was du sagen wolltest.", "Er trug überallhin ein kleines, abgegriffenes Heft bei sich.", "Er schlug das neue Heft auf und nickte."],
  da_vinci: ["Leonardo da Vinci", "15. und 16. Jahrhundert, Italien", "Eine Kopie einer Manuskriptseite", "Neugier ist das beste Geschenk. Danke, dass du mit mir die Vögel beobachtet hast.", "Er schrieb von rechts nach links, spiegelverkehrt, sodass man einen Spiegel zum Lesen brauchte.", "Er sah den Vögeln lange zu und fragte sich, wie sie auf dem Wind ruhen.", "Er nahm es in die Hand und begann sofort zu zeichnen."],
  li_bai: ["Li Bai", "Tang-Dynastie, China", "Eine Kopie einer Gedichtseite", "Solange der Mond da ist, leistet dir jemand Gesellschaft.", "Er starrte auf den Mond vor dem Fenster und murmelte vor sich hin.", "Er bat um Papier und Pinsel, denn ein Gedicht muss frisch geschrieben werden, und fragte sich, was in der Ferne liegt.", "Er nahm den Pinsel und schrieb, und der Mond stand schon am Himmel, bevor die Tusche trocken war."],
  du_fu: ["Du Fu", "Tang-Dynastie, China", "Eine Kopie einer Gedichtseite", "Erst die Wärme gibt einem Gedicht seine Kraft.", "Er zog sein dünnes Gewand enger und sagte, dieser Winter sei besonders kalt.", "Beim Anblick deines Lampenlichts sagte er, es wäre wunderbar, wenn jeder einen warmen Ort zum Wohnen hätte.", "Mit etwas Warmem in der Hand stieß er einen langen Atemzug aus."],
  su_shi: ["Su Shi", "Song-Dynastie, China", "Eine Seite mit Rezept und Vers", "Wie der Tag wird, hängt von dieser einen Mahlzeit ab.", "Er schnupperte und fragte, was in der Küche köchelte, und sagte, er habe einmal selbst einen Schmorbraten erfunden.", "Er sagte, Gedichte könnten warten, das Abendessen aber nicht.", "Er nahm einen Schluck und kniff genießerisch die Augen zusammen."],
  zhang_heng: ["Zhang Heng", "Östliche Han-Dynastie, China", "Eine Kopie einer Sternkarte", "Den Himmel muss man Stück für Stück vermessen.", "Er legte den Kopf in den Nacken zum Nachthimmel und sagte, er wolle die Sterne einen nach dem anderen aufzeichnen.", "Er betrachtete deine Uhr lange und fragte, wie sie so genau gehe.", "Er stellte sie immer wieder nach und lächelte."],
  li_shizhen: ["Li Shizhen", "Ming-Dynastie, China", "Ein gepresstes Kräuterexemplar", "Jede Pflanze hat ihren Nutzen. Verachte keine.", "Er hockte neben einem Blumentopf und studierte genau die Adern eines Blattes.", "Er sagte, er wolle jede Heilpflanze unter der Sonne kennen und eine nach der anderen aufzeichnen.", "Er steckte es ein und hockte sich wieder neben den Blumentopf."],
  lin_daiyu: ["Lin Daiyu", "Eine Figur aus „Der Traum der Roten Kammer“", "Eine Seidenblume", "Es ist ein Segen, dass jemand an einen denkt.", "Sie hustete leise und sagte, der Nachtwind sei ein wenig kalt.", "Mit einem Buch in der Hand fragte sie, ob du etwas hättest, das einem ein wenig besser fühlen lässt.", "Sie nahm es und sagte leise danke."],
  archimedes: ["Archimedes", "Antikes Griechenland", "Ein kleiner Hebel", "Finde den Drehpunkt, der Rest ist nur Zeit.", "Er starrte lange in deine Badewanne, ganz in Gedanken versunken.", "Er sagte, mit einem festen Standpunkt könne er die ganze Welt bewegen.", "Er drehte es um und grinste wie ein Kind."],
  ibn_sina: ["Ibn Sina", "11. Jahrhundert, Persien", "Eine Kopie einer Manuskriptseite", "Die Pflicht eines Arztes ist es, weiterzugeben, was er weiß.", "Er blätterte in deinen Regalen und sagte, ein gutes Buch könne einen Menschen mehr beruhigen als jede Medizin.", "Er sagte, er wolle jede Krankheit, die er gesehen habe, für die Nachkommen aufschreiben.", "Er prüfte es sorgfältig und nickte."],
  al_khwarizmi: ["Al-Chwarizmi", "9. Jahrhundert, Zentralasien", "Eine Kopie einer Seite mit Rechenwegen", "Zerlege ein schweres Problem und geh es Schritt für Schritt an.", "Er zeichnete eine Gleichung auf den Boden und löste sie dir Schritt für Schritt.", "Er fragte, ob deine Karte genau sei, und sagte, er habe selbst eine gezeichnet.", "Er breitete sie aus und begann zu rechnen."],
  ada: ["Ada Lovelace", "19. Jahrhundert, Großbritannien", "Eine Kopie einer Notizseite", "Fantasie und Rechnen sind eigentlich dasselbe.", "Sie sagte, vielleicht könnten Maschinen eines Tages Musik komponieren.", "Sie bat um eine gute Feder, denn ihre Notizen waren noch nicht fertig.", "Sie nahm die Feder und ergänzte sofort eine Zeile in ihren Notizen."],
  ramanujan: ["Srinivasa Ramanujan", "Anfang des 20. Jahrhunderts, Indien", "Eine Kopie einer Notizseite", "Zahlen haben Gefühle, wenn man ihnen nur Gesellschaft leistet.", "Er blätterte in einem alten Heft und sagte, manche Formeln kämen ihm im Schlaf.", "Er sprach vom Essen seiner Heimat, mit einem Glanz in den Augen.", "Er aß langsam und schlug danach sein Heft wieder auf."],
  tagore: ["Rabindranath Tagore", "19. und 20. Jahrhundert, Indien", "Eine Kopie einer Gedichtseite", "Beeile dich weder, erwachsen zu werden, noch, alt zu werden.", "Er sah dem Regen am Fenster zu und sagte, er wolle ein kurzes Gedicht schreiben.", "Er sagte, er habe erst spät im Leben mit dem Malen begonnen und liebe es.", "Er nahm es und schaute hinaus in den Regen."],
  hokusai: ["Katsushika Hokusai", "Edo-Zeit, Japan", "Ein kleines Gemälde einer Welle", "Wer bis zum Ende malt, bleibt immer ein Schüler.", "Er sagte, er habe sein ganzes Leben gemalt und wünsche sich noch ein paar Jahre, um besser zu werden.", "Er sah aus deinem Fenster und sagte, er wolle eine Welle malen.", "Er breitete das Papier aus und lachte beim ersten Strich."],
  murasaki: ["Murasaki Shikibu", "Heian-Zeit, Japan", "Eine Kopie einer Seite der Erzählung", "Geschichten schreibt man für Menschen, die noch nicht geboren sind.", "Sie saß still am Fenster und sagte, sie wolle heute Abend etwas schreiben.", "Sie sah zum Himmel und fragte, ob es ein wenig heller sein könne.", "Als die Lampe brannte, nahm sie den Pinsel und nickte leise."],
  basho: ["Matsuo Basho", "Edo-Zeit, Japan", "Eine Kopie einer Haiku-Seite", "Alles, was dir unterwegs begegnet, ist ein Gedicht.", "Er blickte auf seine Strohsandalen und sagte, der Weg sei noch lang.", "Er sagte, das Schönste an einer Reise sei eine Tasse heißen Tees.", "Er probierte sie an, tat zwei Schritte und nickte lächelnd."],
  ibn_battuta: ["Ibn Battuta", "14. Jahrhundert, Marokko", "Eine Kopie einer Seite aus dem Reisebuch", "Je weiter du gehst, desto besser weißt du, wo dein Zuhause ist.", "Er erzählte endlos von den Städten, die er unterwegs gesehen hatte.", "Er fragte mehrmals, wo genau dein Ort liege.", "Er breitete sie aus und lachte, während er auf eine Stelle darauf zeigte."],
  austen: ["Jane Austen", "18. und 19. Jahrhundert, Großbritannien", "Eine Kopie einer Manuskriptseite", "Auch ein kleiner Tisch kann die ganze Welt tragen.", "Sie schob ihr Manuskript unter eine Schreibunterlage, sobald jemand näher kam.", "Sie sagte, eine heiße Tasse Tee und ein kleiner Tisch genügten für ein Kapitel.", "Sie lächelte und stellte es auf ihren kleinen Tisch."],
  pasteur: ["Louis Pasteur", "19. Jahrhundert, Frankreich", "Eine Kopie einer Seite der Laboraufzeichnungen", "Was man sieht, ist die Wirkung, was man nicht sieht, ist die Ursache.", "Er sah lange auf einen einzigen Wassertropfen und sagte, darin liege eine unsichtbare Welt.", "Er sagte, alles, was Menschen essen und trinken, solle ein wenig sauberer sein.", "Er beugte sich vor und sah mit angehaltenem Atem hin."],
  seacole: ["Mary Seacole", "19. Jahrhundert, Jamaika und Großbritannien", "Ein kleiner Beutel mit Kräutern", "Wo immer mich jemand braucht, ist mein Platz.", "Sie trug einen Beutel mit selbst gemischten Kräutern bei sich und sagte, sie nehme ihn überallhin mit.", "Sie sagte, bei jemandem, dem es nicht gut gehe, beginne sie immer mit einer Schüssel heißer Suppe.", "Sie nickte und steckte es in ihre eigene Tasche."],
  dickinson: ["Emily Dickinson", "19. Jahrhundert, Vereinigte Staaten", "Eine Kopie einer Seite mit kurzen Gedichten", "Hoffnung ist das Ding mit Federn.", "Sie sagte leise, kurze Zeilen bei Nacht lägen ihr am besten.", "Sie bat um ein kleines Heft, gerade groß genug für ein Gedicht.", "Sie schlug das Heft behutsam auf und lächelte, ohne ein Wort."],
  wang_xizhi: ["Wang Xizhi", "Östliche Jin-Dynastie, China", "Eine Kopie einer Kalligrafieseite", "Ob die Schrift gut ist, hängt davon ab, wie ruhig das Herz ist.", "Er erinnerte sich an ein Frühlingsfest, bei dem alle am Bach Gedichte schrieben.", "Er fragte, ob dein Tisch groß genug für ein Blatt Papier sei.", "Er breitete das Papier aus, atmete tief durch und setzte den ersten Strich."],
  zhang_zhongjing: ["Zhang Zhongjing", "Östliche Han-Dynastie, China", "Eine Kopie einer Seite aus dem medizinischen Buch", "Was du gesehen und aufgeschrieben hast, ist Medizin für die, die danach kommen.", "Er sagte, er wolle die Krankheiten, die er gesehen habe, in einem Buch sammeln, um den Nachkommen Leid zu ersparen.", "Er roch an deinem Tee und sagte, er müsse wissen, was für einer es sei.", "Er sah es sich genau an und nickte."],
  euler: ["Leonhard Euler", "18. Jahrhundert, Schweiz", "Eine Kopie einer Seite mit Rechenwegen", "Auch wenn das Licht schwächer wird, kannst du weiterrechnen.", "Er kniff die Augen zusammen, um deine Handschrift zu lesen, und sagte, seine Augen würden schlechter.", "Er sagte, er könne weiterrechnen, auch wenn ein Kind auf seinem Knie klettert.", "Er setzte sie auf und hielt das Papier näher."],
  hippocrates: ["Hippokrates", "Antikes Griechenland", "Ein Weidenblatt", "Schau ein wenig länger hin, warte ein wenig länger, und der Körper hilft sich selbst.", "Er saß lange am Bett, ohne ein Wort, und sah genau hin, bevor er fragte, wie die Nacht gewesen sei.", "Er sagte, der Überlieferung nach habe er einmal Weidenrinde kauen lassen, und dass einfache Kost und Ruhe am wichtigsten seien.", "Er kaute daran, nickte und sagte, es schmecke wie zu Hause."],
  ibn_al_nafis: ["Ibn an-Nafis", "13. Jahrhundert, Syrien und Ägypten", "Eine Kopie einer Manuskriptseite über Lunge und Blut", "Nur genaues Hinsehen führt zu genauem Schreiben.", "Er zeichnete ein Herz auf Papier und sagte, das Blut gehe nicht direkt durch die Scheidewand, sondern fließe einen Bogen durch die Lunge.", "Er sagte, er habe den größten Teil seines Lebens in Krankenhäusern verbracht und sehe am liebsten, wie Kranke langsam gesund werden.", "Er nahm es entgegen und schlug es sofort zum Schreiben auf."],
  omar_khayyam: ["Omar Chayyam", "11. und 12. Jahrhundert, Persien", "Eine Seite mit Kalenderrechnungen", "Zähle die Tage gut, dann kannst du sie gut leben.", "Er zeichnete ein paar Kegelschnitte und sagte, auch kubische Gleichungen ließen sich mit Geometrie lösen.", "Er sagte, er habe den ganzen Abend an Kalenderrechnungen gesessen und wolle jemanden zu einer Partie Schach finden.", "Er stellte die Figuren eine nach der anderen auf und sagte, die Sterne würden heute Nacht bestimmt schön."],
  scheherazade: ["Scheherazade", "Eine Figur aus „Tausendundeine Nacht“", "Eine Geschichtenkerze", "Erzähle eine Geschichte jemandem, der zuhören will, und sie endet nie.", "Sie sagte, sie trage so viele Geschichten in sich, dass eine Nacht nie reichen würde.", "Sie fragte, ob jemand im Haus eine Geschichte hören wolle, am besten vor dem Schlafen.", "Sie stellte die Lampe neben das Bett und begann leise die erste Geschichte."],
  sushruta: ["Sushruta", "Antikes Indien, überlieferter Verfasser eines chirurgischen Textes", "Eine Kopie einer Seite mit Instrumentenzeichnungen", "Ruhige Hände, ein stiller Geist, und denke es vorher einmal durch.", "Er sagte, Chirurgie müsse zuerst an Kürbissen und Lederbeuteln geübt werden, nie gleich an einem Menschen.", "Er wischte jedes Instrument sauber und legte sie aus und sagte, jeder Schritt müsse bedacht sein, bevor die Hand sich bewegt.", "Er zog sie an, sah sie sich an und nickte zufrieden."],
  aryabhata: ["Aryabhata", "5. und 6. Jahrhundert, Indien", "Eine Seite mit Berechnungen von Pi", "Zahlen lügen nicht, solange du bereit bist, noch einmal zu zählen.", "Er zeigte zum Himmel und sagte, die Sterne schienen sich zu drehen, doch vielleicht drehe sich der Boden unter unseren Füßen.", "Er rechnete aus, dass der Kreis zu seinem Durchmesser etwa 3,1416 beträgt, und prüfte es immer wieder nach.", "Er baute es auf, sah hindurch und notierte sorgfältig ein paar Zahlen."],
  le_huu_trac: ["Lê Hữu Trác (Hải Thượng Lãn Ông)", "18. Jahrhundert, Vietnam", "Ein Bündel getrockneter Kräuter", "Das Herz eines Heilers zählt mehr als die Medizin.", "Er sagte, Medizin müsse nicht teuer sein: Eine Pflanze am Feldrand ist auch Medizin, wenn man sie richtig einsetzt.", "Er sagte, Arme müsse man nicht bezahlen lassen, und die Kräuter könne man selbst anbauen.", "Er rieb die Samen zwischen den Fingern und sagte, eine Handvoll, jetzt gesät, reiche nächstes Jahr."],
  raden_saleh: ["Raden Saleh", "19. Jahrhundert, Java", "Eine Kopie eines kleinen Gemäldes", "Wie das Licht fällt, malt man nur richtig, wenn man es ständig beobachtet.", "Er trug ein Skizzenbuch bei sich und konnte den ganzen Nachmittag im Hof sitzen.", "Er malte gern Tiere und wechselndes Wetter und fragte, ob deine Katze stillsitzen würde.", "Er öffnete die Farben und begann, mit Blick zum Fenster Töne zu mischen."],
  sunthorn_phu: ["Sunthorn Phu", "18. und 19. Jahrhundert, Thailand", "Eine Abschrift einer Gedichtseite", "Der Weg ist ein Buch, das man nie ausliest. Gegangen ist man ihn erst, wenn man ihn aufschreibt.", "Er sagte, er schreibe, wo immer er gehe, und jede Landschaft am Weg könne ein Gedicht werden.", "Er reimte gern, und ein halber Satz wurde zu Versen.", "Er zog die Schuhe an, ging eine Runde durchs Zimmer und murmelte eine neue Zeile."],
  al_fihri: ["Fatima al-Fihri", "9. Jahrhundert, Marokko", "Eine Skizze einer Schule", "Ein Ort, an dem Menschen lernen können, ist das beste Erbe.", "Sie fragte, was die Kinder lasen, und sagte, ein Ort zum Lernen sei wichtiger als fast alles andere.", "Sie sagte, sie habe, was ihre Familie ihr hinterließ, für den Bau eines Ortes ausgegeben, an dem Menschen lernen können.", "Sie stellte die Lampe auf den Tisch und schlug ein Buch auf."],
  ibn_khaldun: ["Ibn Chaldun", "14. Jahrhundert, Tunesien und Ägypten", "Eine Kopie einer Seite der Einleitung", "Du siehst weit, weil du klar gesehen hast, was davor war.", "Er sagte, um eine Sache zu verstehen, dürfe man sich nicht auf Legenden allein verlassen, sondern müsse die Ursachen davor und danach betrachten.", "Er trug einen dicken Stapel Manuskript bei sich und sagte, er müsse es noch überarbeiten.", "Er drehte die Lampe höher und widmete sich wieder seinem Manuskript."],
  horton: ["James Africanus Horton", "19. Jahrhundert, Sierra Leone", "Eine Seite mit Wetter- und Fallaufzeichnungen", "Aufzeichnungen sind ehrlich, solange man sie führt.", "Er sagte, die Krankheiten eines Ortes müsse man an dessen Wetter, Wasser und Kost ablesen, und alles müsse festgehalten werden.", "Er hatte in Großbritannien Medizin studiert und führte nach seiner Rückkehr weiter Buch über die Fälle seiner Heimat.", "Er spannte ihn auf, sah zum Himmel und sagte, die Regenzeit brauche eine weitere Spalte."],
  anansi: ["Anansi", "Westafrikanische Märchen der Akan", "Ein kurzer Silberfaden", "Geschichten werden gewebt, Faden für Faden, also nimm dir Zeit.", "Er sagte, alle Geschichten hätten einst ihm gehört und seien erst später in die Welt hinausgetragen worden.", "Er hielt acht Hände beschäftigt und fand sie immer noch zu wenige, und fragte, ob du Ersatzhandschuhe hättest.", "Er streifte sie über und bewegte zufrieden die Finger."],
  imhotep: ["Imhotep", "Altes Ägypten, später als Heiler in Erinnerung", "Eine Skizze eines stufenförmigen Bauwerks", "Alles Hohe beginnt an einem festen Ort.", "Er sagte, um ein hohes Steinbauwerk zu errichten, müsse man das Fundament sorgfältiger vermessen als alle anderen.", "Später sagte man, er habe auch heilen können; er lächelte und bestätigte es weder, noch bestritt er es.", "Er breitete es aus, zeigte auf eine Stelle und sagte, von hier aus werde gemessen."],
  sor_juana: ["Sor Juana Inés de la Cruz", "17. Jahrhundert, Neuspanien (heute Mexiko)", "Eine Kopie einer Gedichtseite", "Ein Buch, das man lesen will, ist das Warten wert.", "Auf ihrem Regal standen mehr Bücher als bei irgendjemandem, und sie sagte, eine ganze Wand reiche nicht.", "Sie sagte, auch Frauen hätten das Recht zu lesen, und sagte es ganz ruhig.", "Sie hielt das Buch, schlug die erste Seite auf und begann still zu lesen."],
  machado: ["Machado de Assis", "19. und 20. Jahrhundert, Brasilien", "Eine Kopie einer Seite mit Korrekturfahnen", "Setze jedes Wort richtig, dann wirst du dem Leser gerecht.", "Er sprach gemächlich und erzählte immer dann einen Witz, wenn man dachte, er werde gleich ernst.", "Er sagte, ein Leser sei wie ein Freund, und beim Schreiben müsse man ihn ab und zu grüßen.", "Er setzte sie auf, sah sich um und lächelte zufrieden."],
  finlay: ["Carlos Finlay", "19. und 20. Jahrhundert, Kuba", "Eine Skizze einer Stechmücke", "Geduld wirkt besser als Streit.", "Er starrte lange auf eine Stechmücke und sagte, etwas Kleines könne die Quelle großen Ärgers sein.", "Er sagte, es mache nichts, dass man seine Idee jahrelang belacht habe; man warte einfach auf den Beweis.", "Er setzte ein Auge daran und sah lange nicht auf."],
  kahlo: ["Frida Kahlo", "20. Jahrhundert, Mexiko", "Eine Papierblume", "Farben lügen nicht, ich male nur, was ich sehe.", "Sie fragte, ob du einen Spiegel hättest, denn sie male sich gern beim Blick in einen.", "Ihre Kleider waren leuchtend bunt, und sie sagte, sie habe zu Hause Affen, Hunde und einen Papagei gehalten.", "Sie breitete sofort die Farben aus und sagte, sie fange mit dem Rot des Schals an."],
  sequoyah: ["Sequoyah", "18. und 19. Jahrhundert, Cherokee", "Eine Kopie einer Seite einer Silbentabelle", "Die eigene Sprache verdient eigene Buchstaben.", "Er sagte, er wolle für seine eigene Sprache ein Schriftsystem schaffen, habe es jahrelang versucht und Zeichen für Zeichen geändert.", "Er trug einen Stapel Papier voller Zeichen bei sich und sagte, er müsse sie noch einmal prüfen.", "Er rückte die Lampe näher und prüfte die Zeichen eines nach dem anderen."],
  tupaia: ["Tupaia", "18. Jahrhundert, Gesellschaftsinseln", "Eine Kopie einer Seekarte", "Auf dem Meer gibt es keine Straßen, nur Richtungen, an die man sich erinnert.", "Er brauchte keine Sternkarte: An der Richtung, in der die Sterne aufgehen, konnte er sagen, wo jede Insel lag.", "Er zeichnete eine Karte des Meeres auf Papier, mit mehr als siebzig Inseln darauf.", "Er breitete sie aus und zeichnete mit dem Finger die fernen Inseln nach."]
});

CY.i18n.register("de", { "title.uncle": "Onkel", "title.aunt": "Tante",
  "visit.fam.med.peer": "{guest} sprach mit {who} über die Medizin, die beide täglich nehmen, und sie erinnerten einander, sie pünktlich zu nehmen.", "visit.fam.sci.peer": "{guest} stand neben {who} am Fenster, und beide fragten sich, ob es morgen regnen werde.", "visit.fam.art.peer": "{guest} trug {who} eine alte Verszeile vor, und beide nickten.", "visit.fam.edu.peer": "{guest} sprach mit {who} über die alten Bücher, die beide gelesen hatten.", "visit.fam.pol.peer": "{guest} schenkte {who} eine Tasse Tee ein, und die beiden saßen nebeneinander, ohne viel zu sagen.", "visit.fam.trv.peer": "{guest} sprach mit {who} über das Wetter und das Essen in ihren Heimatorten." });
CY.i18n.said("de", {
  nightingale: ["Die allererste Forderung an ein Krankenhaus ist, dass es den Kranken keinen Schaden zufügt."],
  zhuge: ["Ohne Schlichtheit gibt es keine Klarheit des Ziels, ohne Stille kein Weitkommen."],
  curie: ["Nichts im Leben ist zu fürchten, es muss nur verstanden werden."],
  galois: ["Ich habe keine Zeit … Ich habe keine Zeit."],
  mozart: ["Lob und Tadel anderer beachte ich nicht. Ich folge einfach meinem eigenen Gefühl."],
  beethoven: ["Alle Menschen werden Brüder."],
  da_vinci: ["Lernen erschöpft den Geist nie."],
  li_bai: ["Der Himmel gab mir Talente, und sie müssen zu etwas taugen; gib tausend Goldstücke aus, sie kommen wieder."],
  du_fu: ["Hätte ich nur zehntausend geräumige Häuser, um alle armen Gelehrten unter dem Himmel zu schützen, alle lächelnd!"],
  su_shi: ["Der wahre Geschmack dieser Welt ist eine schlichte, stille Freude."],
  zhang_heng: ["Der Himmel ist wie ein Ei, und die Erde ist das Eigelb darin."],
  archimedes: ["Heureka! Ich hab's gefunden!"],
  ibn_sina: ["Um eine Sache wirklich zu kennen, muss man ihre Ursachen kennen."],
  ada: ["Die Fantasie ist die Fähigkeit zu entdecken. Sie dringt in die unsichtbaren Welten um uns vor."],
  tagore: ["Möge dein Leben leicht tanzen am Rande der Zeit wie Tau auf der Spitze eines Blattes."],
  hokusai: ["Mit dreiundsiebzig begriff ich ein wenig vom wahren Bau der Tiere, Pflanzen, Bäume, Vögel, Fische und Insekten."],
  basho: ["Ein alter Teich: Ein Frosch springt hinein, das Geräusch des Wassers."],
  austen: ["Nichts geht über das Zuhausebleiben, wenn man echten Komfort will."],
  pasteur: ["Im Feld der Beobachtung begünstigt der Zufall nur den vorbereiteten Geist."],
  dickinson: ["Ich bin Niemand! Wer bist du?"],
  wang_xizhi: ["Blicke ich auf, sehe ich, wie weit das Universum ist; blicke ich hinab, wie reich die Dinge."],
  zhang_zhongjing: ["Suche eifrig die alten Lehren und sammle weithin alle Rezepte."],
  euler: ["In der Welt geschieht nichts, dessen Sinn nicht der eines Maximums oder Minimums wäre."],
  hippocrates: ["Das Leben ist kurz, die Kunst ist lang."],
  scheherazade: ["Und das war erst der Anfang der Geschichte."],
  sor_juana: ["Ich studiere nicht, um mehr zu wissen, sondern um weniger zu ignorieren."],
  kahlo: ["Ich male meine eigene Wirklichkeit."]
});
CY.i18n.register("de", { "corner.rate_tip": "Die +-Zahl ist das Haushaltseinkommen pro Spielstunde bei der Arbeit. Mehr Wohlbefinden bringt mehr." });

CY.i18n.asks("de", {
  "archimedes": ["Gib mir einen Standpunkt, und ich bewege die Erde. Glaubst du mir?", "Ja, aber gib mir erst einen ausreichend langen Hebel.", "Nein. Lass uns darüber streiten.", "Gut! Zeichne mir deinen Hebel, und wir rechnen ihn Zoll für Zoll durch."],
  "nightingale": ["Du bist schon lange beschäftigt. Wer sich um andere kümmert, muss auch schlafen.", "Gut, ich ruhe mich ein wenig aus.", "Nach dieser hektischen Phase.", "Ich halte die Lampe für dich. Geh nur."],
  "zhuge": ["Hast du für den Haushalt einen Plan? Lass mich eine Reihenfolge festlegen.", "Bitte rate mir.", "Ich habe es im Griff. Trink einen Tee.", "Dringendes zuerst, Langsames danach, und vor allem: Reib dich nicht auf."],
  "curie": ["Weißt du, was du jeden Tag tust? Nur wer es versteht, muss nichts fürchten.", "Ich möchte versuchen, es zu verstehen.", "Ich will es einfach hinter mich bringen.", "Dann eins nach dem anderen. Schreib auf, was du nicht verstehst."],
  "galois": ["Gibt es etwas, das du tun willst und wofür nie Zeit war?", "Ja, und ich möchte jetzt damit anfangen.", "Ja, aber es ist nicht der richtige Zeitpunkt.", "Warte nicht. Ich meine es ernst: Warte nicht."],
  "da_vinci": ["Hast du je genau beobachtet, wie ein Vogel zur Ruhe kommt?", "Nein, bring mir das Schauen bei.", "Ja: erst die Flügel, dann die Krallen.", "Genau! Die besten Lehrer sind die, die nichts sagen."],
  "hippocrates": ["Sag, wo fühlst du dich heute am schlechtesten? Denk nicht an Ursachen, nur an das Gefühl.", "Ein wenig müde, und die Schultern sind schwer.", "Nichts, mir geht es gut.", "Mm. Der Körper spricht zuerst, wir hören langsam zu."],
  "su_shi": ["Gedichte können warten, das Abendessen nicht. Was möchtest du essen?", "Eine Schüssel heiße Nudelsuppe.", "Du entscheidest, ich esse alles.", "Gut! Ich finde einen Weg, dass es besser schmeckt, als es aussieht."],
  "li_bai": ["Der Mond ist heute Abend schön. Sag, sollen wir eine Tasse Tee trinken?", "Ja, ich setze mich ein Weilchen zu dir.", "Trink du, ich habe noch zu tun.", "Der Mond wartet auf niemanden, aber er drängt auch niemanden. Bleib ein Weilchen."],
  "du_fu": ["Ich denke oft, wie schön es wäre, wenn jeder ein warmes Haus hätte. Was meinst du?", "Hier ist eines. Ist dir jetzt behaglich?", "Das ist zu schwer; eine Familie zu versorgen genügt.", "Ein Heim zu wärmen heißt, eine Ecke der Welt zu wärmen."],
  "ada": ["Glaubst du, dass eine Maschine eines Tages Dichtung verstehen könnte?", "Vielleicht, wenn jemand es ihr beibrächte.", "Nein, Dichtung ist Sache der Menschen.", "Eine gute Frage. Voreilige Schlüsse wollen wir nicht ziehen, erst die Fantasie voll ausschöpfen."],
  "pasteur": ["Nicht alles Unsichtbare ist nicht da, weißt du. Hast du dir die Hände gewaschen?", "Ja, keine Sorge.", "Ich gehe sie gleich waschen.", "Gut. Der Zufall begünstigt die Vorbereiteten, und die Gesundheit auch."],
  "med.0": ["Hast du heute Wasser getrunken und etwas gegessen? Sorge erst für dich, dann für die anderen.", "Ja, beides.", "Noch nicht, ich gehe jetzt.", "Gut. Das ist die billigste Medizin."],
  "med.1": ["Wie schläfst du? Schlaf ist das älteste Rezept.", "Ganz gut.", "Nicht gut, ich wache oft auf.", "Schreib es auf; heute Nacht überlegen wir uns gemeinsam etwas."],
  "sci.0": ["Etwas beschäftigt mich: Warum werden Erwachsene weich, sobald ein Kind weint?", "Weil wir seine Traurigkeit nicht ertragen.", "Wahrscheinlich die Evolution.", "Interessant. Beide Erklärungen verdienen ein Experiment."],
  "sci.1": ["Ist dir aufgefallen, dass die Schatten heute etwas kürzer sind als gestern?", "Jetzt, wo du es sagst, ja.", "Mir ist es nicht aufgefallen.", "Die Welt verändert sich ständig; wir sind nur zu beschäftigt hinzusehen."],
  "art.0": ["Ein Rätsel für dich: ein Wort für deine Stimmung heute.", "Ruhig.", "Hektisch.", "Ein gutes Wort. Ich merke es mir; vielleicht landet es einmal in einem Gedicht."],
  "art.1": ["Das Licht in deinem Haus ist wunderschön. Hast du je in der Dämmerung nichts getan und nur zugesehen?", "Manchmal.", "Nein, ich bin immer beschäftigt.", "Versuch es. Die besten Bilder und Gedichte beginnen oft im Müßiggang."],
  "edu.0": ["Was hast du in letzter Zeit gelesen? Es muss kein Buch sein, alles zählt.", "Ein Bilderbuch für Kinder.", "Gar nichts.", "Bilderbücher zählen, und sie gehören zu den sorgfältigst geschriebenen."],
  "edu.1": ["Lass mich fragen: Soll Lehren dazu dienen, dass man sich erinnert, oder dass man fragt?", "Dass man fragt.", "Dass man sich erinnert.", "Beide Antworten stimmen, nur die Reihenfolge ist verschieden."],
  "pol.0": ["Ein Haushalt ist wie ein kleines Reich: einer kocht, einer fegt, einer hält den Frieden. Wer bist du?", "Von allem ein bisschen.", "Ich halte den Frieden.", "Dann hast du den schwersten Posten von allen."],
  "pol.1": ["Erst das Ganze sehen, dann die Einzelheiten. Was ist das Ganze deines Hauses heute?", "Dass alle in Sicherheit sind.", "Darüber habe ich nicht nachgedacht.", "Sicherheit genügt. Viele jagen diesem Wort ein Leben lang nach."],
  "trv.0": ["Fern der Heimat vermisse ich nicht die Landschaft, sondern eine Schüssel warmes Essen. Und du?", "Genauso.", "Ich vermisse die Stille.", "Jeder hat sein eigenes Heimweh. Beide sind es wert, bewahrt zu werden."],
  "trv.1": ["Hast du je gedacht, dass dieses Haus der weiteste Weg ist, den du gegangen bist?", "Nein, aber es klingt richtig.", "Ja, ich gehe ihn jeden Tag.", "Genau. Die längsten Reisen verlassen oft nie die Tür."]
});
CY.i18n.register("de", { "shop.sec_home": "Fürs Zuhause", "shop.sec_gifts": "Geschenke für Besucher", "shop.gift_note": "Ein Geschenk zählt nur, wenn es das ist, was der Besucher wirklich braucht. Höchstens drei von jeder Sorte. Zum Schenken im Aktionskreis des Besuchers „Beschenken“ gedrückt halten.", "gift.empty": "Der Rucksack ist leer. Tippe auf die Geldanzeige und schau im Geschenkbereich des Ladens vorbei." });
CY.i18n.register("de", { "start.lead_title": "Wer bist du?", "start.lead_note": "Wähle ein Familienmitglied, und du bist diese Person. Du kannst das jederzeit ändern: Tippe oben rechts auf 👥 und wähle bei einer Person „{btn}“.", "start.next": "Weiter", "start.house_title": "Das alte Haus", "start.house_p1": "Du bist ins alte Haus zurückgekehrt. Die Menschen, um die du dich kümmern willst, wohnen hier, und du arbeitest und sorgst für sie unter einem Dach.", "start.house_p2": "Das Hoftor klickt leise, und {name} kommt herein, eine Öllampe in der Hand.", "start.house_say": "„Was für ein interessanter Ort. Ich leihe mir nur für kurze Zeit ein Bett und bin bald wieder fort.“", "start.house_p3": "Von nun an werden noch mehr Menschen durch dieses Tor kommen und ein oder zwei Tage bleiben." });

CY.i18n.cards("de", {
  arrive: "{n} trat durch die Haustür und bat darum, ein paar Tage bleiben zu dürfen.",
  ok: "Vor dem Abschied ließ {n} etwas zurück: {s}. Dazu sagte {n}: „{q}“",
  miss: "{n} bedankte sich und ging zurück durch die Tür."
}, {
  sun_simiao: ["Sun Simiao", "Tang-Dynastie, China", "Eine Kopie einer Seite mit Rezepten", "Eine Arznei muss nicht teuer sein, nur die richtige für die Krankheit.", "Er sagte, ein Heiler dürfe nicht zwischen arm und reich unterscheiden; wer kommt, ist ein Kranker, und alle werden gleich behandelt.", "Er sammelte gern Kräuter in den Bergen und sagte, die besten Heilmittel wüchsen oft dort, wo niemand hinsieht.", "Er wog die Samen in der Handfläche und sagte, diese Handvoll könne vielen Menschen helfen."],
  heo_jun: ["Heo Jun", "16. und 17. Jahrhundert, Joseon-Korea", "Eine Kopie einer Seite mit Kräuterzeichnungen", "Ein medizinisches Buch, das einfache Leute lesen können, ist ein gutes Buch.", "Er sagte, Heilpflanzen sollten auch für einfache Leute erkennbar sein, und gab deshalb jeder ihren örtlichen Namen.", "Er sagte, Vorbeugen sei besser als Heilen, und den Körper täglich zu pflegen sei die beste Medizin.", "Er legte die Decke über die Knie und nickte; nun war es warm."],
  hanaoka: ["Hanaoka Seishu", "Edo-Zeit, Japan", "Eine Kopie einer Seite mit Rezepturnotizen", "Einem Menschen den Schmerz zu ersparen, ist die erste Güte eines Heilers.", "Er sagte, er habe viele Jahre an einem Trank gearbeitet, der den Kranken schlafen lässt, und werde ihn erst einsetzen, wenn er sicher sei.", "Er sagte, bevor die Hände zu arbeiten beginnen, müsse der Kranke zuerst seine Angst verlieren.", "Er zog sie an und sagte, sind die Finger warm, so ist auch der Geist ruhig."],
  charaka: ["Charaka", "Antikes Indien, überlieferter Verfasser der Charaka Samhita", "Eine Kopie einer Seite mit Anamnese-Notizen", "Eine Frage mehr ist mehr wert als ein Rezept mehr.", "Er sagte, ein Arzt solle immer wieder fragen: Was hast du gegessen, wie hast du geschlafen, was beschäftigt dich?", "Er sagte, ein guter Arzt bleibt wie ein Freund an der Seite des Kranken.", "Er hielt die heiße Suppe und sagte, man solle sich erst aufwärmen, bevor man spricht."],
  razi: ["Al-Razi", "9. und 10. Jahrhundert, Persien und Bagdad", "Eine Kopie einer Seite mit Fallaufzeichnungen", "Oft hinsehen, sorgfältig aufzeichnen, und erst dann sprechen.", "Er sagte, er schreibe jeden Fall eines Kranken auf, und ein Fall sei mehr wert als ein Buch.", "Er sagte, am Krankenbett vertraue man der eigenen Beobachtung, nicht nur den alten Büchern.", "Er beugte sich nah heran und sagte lange nichts."],
  zahrawi: ["Al-Zahrawi", "10. und 11. Jahrhundert, Al-Andalus", "Eine Kopie einer Seite mit Instrumentenzeichnungen", "Ein Handwerk muss von Generation zu Generation aufgezeichnet werden, sonst geht es verloren.", "Er zeichnete jedes chirurgische Instrument, das er benutzte, und sagte, ein Bild sei mehr wert als tausend Worte.", "Er sagte, die Hände eines Chirurgen müssten ruhig sein, der Geist sorgfältig und die Werkzeuge sauber.", "Er legte es auf den Tisch, warf einen Blick auf die Uhr und sagte, Pünktlichkeit sei das Wichtigste."],
  galen: ["Galen", "2. Jahrhundert, Pergamon und Rom", "Eine Kopie einer Seite mit Beobachtungsnotizen", "Viel schauen, viel denken, dann schließen.", "Er sagte, ein Arzt solle auch Philosoph sein: erst beobachten lernen, dann denken.", "Er sagte, ein guter Arzt habe erst das Recht, von Krankheit zu sprechen, wenn er den Puls mit eigener Hand gefühlt hat.", "Er legte sich den Schal um die Schultern und schlug das Buch auf."],
  vesalius: ["Andreas Vesalius", "16. Jahrhundert, Flandern", "Eine Kopie einer Seite einer anatomischen Tafel", "Vertraue deinen Augen und den Linien, die du zeichnest.", "Er sagte, was die Bücher zeigten, stimme nicht mit dem überein, was er sehe, also prüfe er alles mit eigenen Augen.", "Er sagte, um den Körper zu verstehen, müsse man seinen Aufbau Teil für Teil zeichnen.", "Er mischte eine Farbe und sagte, dieser Strich müsse sehr genau sein."],
  jenner: ["Edward Jenner", "18. und 19. Jahrhundert, Großbritannien", "Eine Skizze einer Kuh", "Erst beobachten, dann nachdenken und erst zuletzt handeln.", "Er sagte, ihm sei aufgefallen, dass Milchmädchen selten die Pocken bekämen, und das verdiene sorgfältiges Nachdenken.", "Er sagte, gute Antworten stecken oft in der alltäglichen Beobachtung.", "Er zog die Schuhe an und sagte, er wolle über Land gehen und sich die Kühe ansehen."],
  blackwell: ["Elizabeth Blackwell", "19. Jahrhundert, Großbritannien und die Vereinigten Staaten", "Eine Kopie eines Zulassungsschreibens", "Ist eine Tür einmal geöffnet, können die dahinter hindurchgehen.", "Sie sagte, viele Schulen hätten sie abgewiesen, bis eine sie schließlich aufnahm.", "Sie sagte, Frauen könnten gute Ärztinnen sein, wenn ihnen nur jemand eine Chance gebe.", "Sie zog den Mantel an, ihre Augen leuchteten auf, und sie sagte, heute Nacht werde sie lange lesen."],
  chagas: ["Carlos Chagas", "19. und 20. Jahrhundert, Brasilien", "Eine Seite mit Skizzen unter dem Mikroskop", "Krankheit wächst aus dem Alltag, also such sie dort.", "Er sagte, in einem kleinen Dorf habe er ein kleines Insekt mit einer Krankheit in Verbindung gebracht.", "Er sagte, um eine Krankheit zu verstehen, müsse man Insekt, Menschen und Häuser zugleich verstehen.", "Er spannte den Schirm gegen die Sonne und beugte sich lange über die Linse."]
});
CY.i18n.said("de", { sun_simiao: ["Der Mensch ist mehr wert als tausend Goldstücke; ein Rezept, das einem Menschen hilft, nützt mehr als Gold."], galen: ["Der beste Arzt ist auch ein Philosoph."] });
CY.i18n.register("de", { "shop.sec_bed": "Betten", "shop.bed_note": "Die Betten bestimmen, wie viele Menschen zu Hause wohnen können. Familie und Besucher belegen je eines. Sie sind teuer, also spare in Ruhe. Babys schlafen in Wiegen und brauchen kein Bett.", "shop.bed_slot": "Ein Bett dazu", "shop.bed_slot_fx": "Ein Bett mehr, und es kann ein Mensch mehr hier wohnen und ein Besucher mehr bleiben. Sind die Betten aufgebraucht, kann niemand Neues dazukommen, und es kommt kein neuer Besucher.", "shop.beds_now": "Betten {n}/{m}, {u} belegt", "shop.full": "Alle Betten gekauft", "shop.sec_daily": "Alltagsdinge", "shop.sec_decor": "Dekoration", "shop.decor_note": "Dekoration dient nur dem Aussehen und hat keinerlei Wirkung auf irgendeinen Wert.", "shop.cabinet_fx": "Steht im Wohnzimmer und bewahrt die Andenken auf, die Besucher zurücklassen. Fahre mit der Maus über ein Andenken, um zu sehen, von wem es stammt. Nur fürs Auge, ohne Wirkung auf irgendeinen Wert.", "shop.decor1_fx": "Eine kleine Pflanze im Wohnzimmer. Nur fürs Auge, ohne Wirkung auf irgendeinen Wert.", "shop.decor2_fx": "Ein Teppich und eine Stehlampe im Wohnzimmer. Nur fürs Auge, ohne Wirkung auf irgendeinen Wert.", "shop.decor3_fx": "Ein Radio und eine Pflanze im Wohnzimmer. Nur fürs Auge, ohne Wirkung auf irgendeinen Wert.", "shop.gift_note": "Nicht jedes Geschenk trifft den Geschmack des Besuchers: Ein geliebtes steigert die Zuneigung stark, ein gewöhnliches nur wenig. Ist die Zuneigung groß genug, hinterlässt der Besucher ein Gegengeschenk. Höchstens drei von jeder Sorte. Zum Schenken im Aktionskreis des Besuchers „Beschenken“ gedrückt halten.", "add.no_bed": "Es ist kein Bett mehr frei. Kaufe im Laden ein Bett, bevor du jemanden hinzufügst.", "gift.fav": "Zuneigung {n}/{m}", "gift.fav_ok": "Erreicht, ein Gegengeschenk bleibt zurück", "gift.mild": "{name} hat es angenommen und sich bedankt, wirkte aber nicht besonders erfreut.", "field.med": "Medizin", "field.sci": "Wissenschaft und Technik", "field.art": "Literatur und Kunst", "field.edu": "Gelehrsamkeit und Bildung", "field.pol": "Politik und Militär", "field.trv": "Reisen und Seefahrt" });
