CY.i18n.register("de", {"loc.kids": "Kinderzimmer", "shop.bed_slot": "Gästebett dazu", "shop.bed_note": "Das Haus hat drei Schlafzimmer mit je zwei Betten: für das Paar, für die Kinder und für die Älteren. Diese Familienbetten sind kostenlos, die Familie hat höchstens sechs Mitglieder. Das Gästezimmer hat anfangs ein Bett für Zeitreisende, bis zu drei sind möglich, zwei weitere kannst du kaufen. Babys schlafen in Wiegen und brauchen kein Bett.", "shop.bed_slot_fx": "Ein Gästebett mehr, ein Reisender mehr.", "shop.beds_now": "Gästebetten {n}/{m}, belegt {u}", "add.no_bed": "Alle sechs Familienbetten sind belegt, es kann niemand mehr einziehen."});
