CY.i18n.register("de", {"add.away": "Tagsüber", "add.away_none": "Bleibt zu Hause", "add.away_work": "Geht zur Arbeit", "add.away_school": "Geht zur Schule", "add.away_note": "Wer aus dem Haus geht, ist tagsüber weg und kommt pünktlich zurück. Diese Person kann nicht die Hauptfigur sein, und bei kleinen Kindern bleibt ein Erwachsener zu Hause.", "preset.couple_baby.label": "Ein Paar mit Baby", "preset.couple_baby.note": "Beide arbeiten im Homeoffice, mit einem Neugeborenen, das kaum jemanden in Ruhe schlafen oder essen lässt", "preset.dual_work.label": "Zwei Berufstätige, Großeltern helfen", "preset.dual_work.note": "Mama und Papa gehen arbeiten, Opa und Oma hüten das Baby bis zum Abend", "preset.single_parent.label": "Alleinerziehende Mama, Oma, ein Kind", "preset.single_parent.note": "Mama arbeitet, das Kind geht zur Schule, und Oma wartet zu Hause auf sie", "preset.summer.label": "Sommerferien, großer Bruder hütet den kleinen", "preset.summer.note": "Mama und Papa sind arbeiten, und der fünfzehnjährige große Bruder ist zu Hause und passt auf den kleinen auf", "preset.threegen.label": "Drei Generationen", "preset.threegen.note": "Opa und Oma, Mama und Papa, ein Baby, alle zu Hause, jeder in seinem eigenen Rhythmus", "preset.elder_care.label": "Ein Paar pflegt einen Älteren", "preset.elder_care.note": "Beide arbeiten im Homeoffice, und Opa hat Diabetes und Bluthochdruck, er braucht Erinnerungen an die Tabletten", "preset.solo_pets.label": "Eine Person, eine Katze, ein paar Pflanzen", "preset.solo_pets.note": "Niemand sonst, nur ein Mensch und die kleinen Leben, um die er sich kümmert", "preset.name.grandpa": "Opa", "preset.name.waipo": "Oma", "preset.name.waigong": "Opa", "preset.name.husband": "Ehemann", "preset.name.wife": "Ehefrau", "preset.name.son": "Sohn", "preset.name.teen": "Großer Bruder"});
